export const SOURCES: CourseSource[] = [
  { id: 'meditation-goyal', title: 'Goyal et al. · 2014 · Meta-analysis of meditation programs (JAMA Internal Medicine)', url: 'https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754', type: 'research', finding: 'From 18,753 records screened, 47 randomized trials with 3,515 participants were included. Mindfulness meditation programs showed small improvements, with moderate-strength evidence, in anxiety (0.38 at 8 weeks; 0.22 at 3–6 months), depression (0.30; 0.23) and pain (0.33); evidence for stress/distress and mental-health-related quality of life was low. There was no evidence that meditation programs were better than active treatments such as drugs, exercise or other behavioral therapies.', limitation: 'Evidence was insufficient, or no effect was found, for outcomes such as positive mood, attention, sleep and weight. Programs varied widely in length and content, and this short course was not tested. The abstract and key points on the article page were read.' },
  { id: 'meditation-body-scan', title: 'Gan, Zhang & Chen · 2022 · Meta-analysis of the body scan (Applied Psychology: Health and Well-Being)', url: 'https://doi.org/10.1111/aphw.12366', type: 'research', finding: 'Across 14 studies of the body scan practiced on its own, it produced only a small increase in mindfulness compared with passive controls (g = 0.268). The authors concluded that the body scan alone is not effective enough to improve health-related outcomes; dropout was low in longer practice periods.', limitation: 'Study quality was low and results varied widely between studies. Only the abstract was read.' },
  { id: 'meditation-lovingkindness', title: 'Zeng et al. · 2015 · Meta-analysis of loving-kindness meditation and positive emotions (Frontiers in Psychology)', url: 'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full', type: 'research', finding: 'Across 24 studies (1,759 people), randomized trials showed that loving-kindness meditation increased daily positive emotions compared with waitlist controls (high-arousal positive emotions g = 0.395; low-arousal positive emotions g = 0.392). Practices focused on loving-kindness (g = 0.424) gave clearer results than practices focused on compassion (g = 0.286, with a confidence interval that included zero).', limitation: '38.9% of the studies reviewed had a high risk of bias; expectation effects and self-selected volunteers may inflate the results. Only four studies compared the practice with another active method, and the analysis looked only at positive emotions.' },
  { id: 'mental-practice', title: 'Toth et al. · 2020 · Mental practice meta-analysis, 24 years later (Psychology of Sport and Exercise)', url: 'https://www.sciencedirect.com/science/article/abs/pii/S1469029219301530', type: 'research', finding: 'Replicating the method of Driskell, Copper and Moran’s 1994 meta-analysis, this study examined 115 effects from 37 studies published between 1995 and 2018. After publication-bias analyses, mental practice (rehearsing a task in the mind without moving) had a small but significant positive effect on performance (r = 0.131, compared with r = 0.255 in the 1994 analysis). The effect depended on practice duration, task type and type of imagery.', limitation: 'The studies are mostly about movement and skill performance; they do not test personality change, mood or illness outcomes. The abstract on the publisher’s page was read.' },
  { id: 'meditation-adverse', title: 'Farias et al. · 2020 · Systematic review of adverse effects in meditation (Acta Psychiatrica Scandinavica)', url: 'https://pubmed.ncbi.nlm.nih.gov/32820538/', type: 'research', finding: 'From 6,742 records, 83 studies (6,703 people) were reviewed. The overall prevalence of adverse effects was 8.3% (3.7% in experimental studies, 33.2% in observational studies). The most commonly reported were anxiety, depression and cognitive anomalies, and adverse effects also occurred in people with no previous history of mental health problems.', limitation: 'Studies measured adverse effects in different and often incomplete ways, so the prevalence estimate is uncertain, and it is not clear how many of these effects were caused directly by meditation. Only the abstract was read.' },
  { id: 'meditation-nccih', title: 'NCCIH · Meditation and mindfulness: effectiveness and safety', url: 'https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety', type: 'guidance', finding: 'The US National Center for Complementary and Integrative Health notes that meditation is generally considered low-risk but that research on harms is limited, and cites a 2020 review in which about 8% of participants experienced a negative effect. It stresses that meditation should not replace conventional medical care or be a reason to postpone seeing a doctor about a health problem.', limitation: 'General US public guidance. In an emergency, call your local emergency number.' },
  { id: 'meditation-mind-wandering-cycle', title: 'Hasenkamp et al. · 2012 · Mind wandering and attention during focused meditation (NeuroImage)', url: 'https://www.sciencedirect.com/science/article/abs/pii/S1053811911007695', type: 'research', finding: 'Fourteen experienced meditators practiced breath-focused meditation in an fMRI scanner and pressed a button whenever they noticed their mind had wandered, then returned to the breath. The researchers described a repeating cycle of four phases: mind wandering, awareness of mind wandering, shifting attention back, and sustained focus. Different brain networks were more active in different phases (the default mode network during mind wandering, the salience network during awareness, executive regions during shifting and focus), and some activity patterns were linked with lifetime meditation experience.', limitation: 'A small brain-imaging study of 14 experienced meditators; it describes what happens during practice and does not show health benefits or prove that practice causes the brain differences. The abstract on the publisher’s page was read.' },
  { id: 'meditation-trauma-sensitive', title: 'David Treleaven · Trauma-sensitive mindfulness (davidtreleaven.com)', url: 'https://davidtreleaven.com/', type: 'guidance', finding: 'Treleaven, an educator who trains mindfulness teachers, warns that mindfulness can unintentionally activate symptoms of traumatic stress, and that people with trauma may experience flashbacks, dysregulation or dissociation during practice that turns attention inward. His site offers training and resources to help teachers and practitioners avoid these pitfalls.', limitation: 'An educator’s website, not a study. Only the homepage was read; it does not list specific adjustments, so the suggestions in this course (eyes open, shorter sits, an outward anchor, a trained teacher) are common safety practice rather than findings from this page.' },
  { id: 'meditation-kabat-zinn', title: 'Jon Kabat-Zinn · Full Catastrophe Living (revised edition, 2013)', url: 'https://www.penguinrandomhouse.com/books/89149/full-catastrophe-living-revised-edition-by-jon-kabat-zinn-preface-by-thich-nhat-hanh-foreword-by-joan-borysenko/', type: 'technique', finding: 'Kabat-Zinn describes the mindfulness-based stress reduction (MBSR) program he developed at the University of Massachusetts Medical School: breath awareness, the body scan, sitting meditation, mindful yoga and bringing attention to everyday activities.', limitation: 'Mindfulness programs have shown small-to-moderate benefits in research, but reading the book is not the same as an eight-week program with a teacher. The book and programs do not replace diagnosis or treatment.' },
  { id: 'meditation-benson', title: 'Herbert Benson · The relaxation response (Harvard Health summary)', url: 'https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598', type: 'technique', finding: 'Benson’s method: sit quietly with eyes closed, relax the muscles, silently repeat a chosen word, sound, phrase or prayer, and let intruding thoughts pass while returning to the focus; practice regularly for 10–20 minutes a day.', limitation: 'This page is a blog post and offers no numerical research data. The method is not a treatment and does not replace a doctor’s advice for blood pressure, heart or digestive problems.' },
  { id: 'meditation-thich-nhat-hanh', title: 'Thich Nhat Hanh · Plum Village · Walking meditation', url: 'https://plumvillage.org/mindfulness/mindfulness-practice/walking-meditation', type: 'technique', finding: 'Plum Village teaches matching steps to the breath (two or three steps on the in-breath, three or four on the out-breath), feeling the moment the foot touches the ground, relaxing the shoulders and arms, and opening attention to the sounds and sights around you; it says this walking can be done anywhere.', limitation: 'A traditional practice guide; large, high-quality studies of walking meditation specifically are limited. In traffic and crowds, safety comes first.' },
  { id: 'meditation-salzberg', title: 'Sharon Salzberg · Lovingkindness (1995; 25th anniversary edition 2020)', url: 'https://www.sharonsalzberg.com/lovingkindness', type: 'technique', finding: 'Salzberg teaches four qualities from the Buddhist tradition, loving-kindness, compassion, sympathetic joy (rejoicing in others’ happiness) and equanimity, through meditations that direct short phrases of good wishes first to yourself and then, in turn, to others.', limitation: 'Loving-kindness meditation has been linked with small-to-moderate increases in positive emotions, but many of the studies carry a high risk of bias. Sending good wishes to someone you find difficult does not mean giving up your boundaries.' },
  { id: 'dispenza-breaking-habit', title: 'Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)', url: 'https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/', type: 'technique', finding: 'Dispenza proposes a meditation that expands step by step over four weeks: settling into the body and the present moment, noticing and admitting the old pattern of feeling and thinking you want to change, letting it go, recognizing and interrupting the moments it switches on during the day, and rehearsing the new self you want to become together with its emotion.', limitation: 'Mental rehearsal and noticing habits fit with research. The book’s claims about changing reality through quantum physics, influencing genes and healing illness with thought are not supported by science; do not change your treatment because of this method.' },
];

